import{_ as r,c as l,o as e,ak as o}from"./chunks/framework.CtX3_w5e.js";const _=JSON.parse('{"title":"economy","description":"","frontmatter":{"sidebar":false,"pageClass":"timeline-page","title":"economy","hugoSource":"others/economy.md","outline":[1,6]},"headers":[],"relativePath":"knowledge/others/2026-11-17-economy.md","filePath":"knowledge/others/2026-11-17-economy.md","lastUpdated":1794887319000}'),n={name:"knowledge/others/2026-11-17-economy.md"};function i(t,a,s,h,d,g){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="_2025-反内卷" tabindex="-1">2025 反内卷 <a class="header-anchor" href="#_2025-反内卷" aria-label="Permalink to “2025 反内卷”">​</a></h1><ul><li>本轮反内卷法治化与市场化结合，上一轮去产能主要以行政主导模式 #财经-2025-16 <ul><li>上一轮去产能，中央设定产能淘汰硬指标（如钢铁去产能1.5亿吨），纳入地方政府考核体系，通过“一刀切”关停、限产实现快速出清。 <ul><li>本轮“反内卷”政策，具有一系列明确的法律约束，即新修订的《反不正当竞争法》明确禁止“低于成本价倾销”，建立公平竞争审查制度。</li><li>同时，更为注重市场引导：通过产能置换指标交易（如水泥行业每新增1吨产能需退出1.5吨旧产能）、行业协会自律倡议（如光伏企业集体减产30%）实现渐进式出清。</li></ul></li><li>同时，上一轮去产能主要为国企主导实施。国有企业承担80%钢铁去产能任务，政策执行刚性强。本轮行业“反内卷”，新兴行业（如光伏、汽车等）民企占比超70%，政策更依赖行业自发协调（如中汽协倡议统一供应商账期）而非行政命令。</li><li>同时，面对的行业也不一样。本轮“反内卷”所对应的是部分先进制造业。由于部分先进制造业出海，前期按照全球需求进行产能布局，外需回落或暂时的贸易壁垒才加剧了供需错配压力。</li><li>本轮行业“反内卷”面临总需求疲软，通货紧缩的宏观背景；上一轮去产能时，需求端支撑，价格传导顺畅。</li></ul></li><li>对一些工业和制造业行业而言，“反内卷”也势必将导致一定程度的“去产能”。但不意味着以“去产能”为核心目的来推动“反内卷”，更不适合刚性的以产量和投资下降等产能去化指标来衡量“反内卷”效果。由于本轮调整的行业范围与性质较上一轮更为复杂，“反内卷”必须坚持以纠正市场失灵，建立公平竞争的市场秩序为最终目标的改革思路，而不能变成新一轮的行政性“去产能”。本轮行业反内卷的核心是提质，走高质量发展道路，而非简单的“去产能”。</li></ul><h1 id="什么是适度宽松的货币政策" tabindex="-1">什么是适度宽松的货币政策？ <a class="header-anchor" href="#什么是适度宽松的货币政策" aria-label="Permalink to “什么是适度宽松的货币政策？”">​</a></h1><h1 id="通货膨胀为什么有利于企业提高利润" tabindex="-1">通货膨胀为什么有利于企业提高利润？ <a class="header-anchor" href="#通货膨胀为什么有利于企业提高利润" aria-label="Permalink to “通货膨胀为什么有利于企业提高利润？”">​</a></h1><p>通货膨胀在一定条件下可能对企业利润产生积极影响，主要原因如下：</p><hr><h3 id="_1-价格上涨带动收入增长" tabindex="-1">1. <strong>价格上涨带动收入增长</strong> <a class="header-anchor" href="#_1-价格上涨带动收入增长" aria-label="Permalink to “1. 价格上涨带动收入增长”">​</a></h3><ul><li><strong>产品提价能力</strong>：通货膨胀推高整体价格水平时，企业可能将成本上涨（如原材料、人工）转嫁给消费者，提高产品售价。若需求弹性较小（消费者对价格不敏感），销售收入增长会快于成本增长，从而扩大利润空间。</li><li><strong>名义收入增加</strong>：即使实际销量不变，价格上涨会直接推高企业的名义收入，在财务报表上体现为利润上升。</li></ul><hr><h3 id="_2-债务实际价值下降" tabindex="-1">2. <strong>债务实际价值下降</strong> <a class="header-anchor" href="#_2-债务实际价值下降" aria-label="Permalink to “2. 债务实际价值下降”">​</a></h3><ul><li><strong>减轻债务负担</strong>：企业若持有固定利率债务，通货膨胀会降低债务的实际价值（未来偿还的货币购买力下降）。例如，企业借入100万元，通胀率为10%时，第二年这笔债务的实际价值相当于约90万元，变相减少企业负担。</li><li><strong>杠杆效应</strong>：资产价值随通胀上升，而负债名义值不变，可能改善企业资产负债表，增强融资能力。</li></ul><hr><h3 id="_3-库存收益-存货利润" tabindex="-1">3. <strong>库存收益（存货利润）</strong> <a class="header-anchor" href="#_3-库存收益-存货利润" aria-label="Permalink to “3. 库存收益（存货利润）”">​</a></h3><ul><li><strong>前期低成本库存增值</strong>：持有大量原材料或成品库存的企业，在通胀期间可按更高价格出售库存，形成“存货利润”。例如，以低价购入的原材料在生产后以高价卖出，利润被放大。</li><li><strong>会计利润提升</strong>：在先进先出（FIFO）会计方法下，早期低成本库存被先计入成本，当期收入按高价匹配，利润虚增（但需注意税务影响）。</li></ul><hr><h3 id="_4-刺激消费与投资需求" tabindex="-1">4. <strong>刺激消费与投资需求</strong> <a class="header-anchor" href="#_4-刺激消费与投资需求" aria-label="Permalink to “4. 刺激消费与投资需求”">​</a></h3><ul><li><strong>提前消费</strong>：若消费者预期未来价格继续上涨，可能提前购买商品，短期提振企业销量。</li><li><strong>资产升值预期</strong>：通胀环境下，企业持有的不动产、设备等资产名义价值上升，可能通过资产重估或抵押贷款获得额外收益。</li></ul><hr><h3 id="_5-工资调整滞后" tabindex="-1">5. <strong>工资调整滞后</strong> <a class="header-anchor" href="#_5-工资调整滞后" aria-label="Permalink to “5. 工资调整滞后”">​</a></h3><ul><li><strong>人工成本暂时偏低</strong>：工资调整通常滞后于物价上涨，短期内企业用工成本实际下降，利润率扩大（但长期可能引发员工不满或劳动力流失）。</li></ul><hr><h3 id="需注意的风险与限制" tabindex="-1">需注意的<strong>风险与限制</strong>： <a class="header-anchor" href="#需注意的风险与限制" aria-label="Permalink to “需注意的风险与限制：”">​</a></h3><ol><li><strong>成本传导不畅</strong>：若市场竞争激烈或需求疲软，企业无法完全转嫁成本，利润反而受压。</li><li><strong>恶性通胀破坏经济</strong>：持续高通胀会导致消费者购买力锐减、供应链混乱，最终损害企业长期经营。</li><li><strong>利率上升压力</strong>：央行可能加息抑制通胀，增加企业融资成本。</li></ol><hr><h3 id="总结" tabindex="-1">总结： <a class="header-anchor" href="#总结" aria-label="Permalink to “总结：”">​</a></h3><p>通货膨胀对企业利润的促进作用主要体现在<strong>价格传导能力</strong>、<strong>债务稀释</strong>和<strong>库存收益</strong>等方面，但高度依赖行业特性、市场结构和通胀程度。合理利用通胀环境可提升短期利润，但企业需警惕长期经济失衡风险。</p><h1 id="mess" tabindex="-1">mess <a class="header-anchor" href="#mess" aria-label="Permalink to “mess”">​</a></h1><ul><li>沿海地区高歌猛进的人工智能、大模型、具身智能、物联网、工业互联网等等，必将给内地相对传统的产业进一步赋能，带来进一步的效率提升</li></ul>',28)])])}const m=r(n,[["render",i]]);export{_ as __pageData,m as default};
